if (!$json.notification_id || !$json.lease_token || !$json.payload) throw new Error('Invalid claimed Teams job');
if ($json.channel !== 'teams') throw new Error('Unexpected notification channel');
const p = $json.payload;
if (p.contract_version !== 'notification-v1') throw new Error('Unsupported notification contract');
const safeText = (value,max=300) => String(value ?? 'Non renseigné').replace(/[\u0000-\u001f\u007f]+/g,' ').replace(/\s+/g,' ').trim().slice(0,max).replace(/\\/g,'\\\\').replace(/([*_{}\[\]()#+\-.!|~])/g,'\\$1').replace(/</g,'‹').replace(/>/g,'›') || 'Non renseigné';
const factLines = (p.analysis.observed_facts ?? []).slice(0,5).map(item => `• ${safeText(item.statement_fr,240)}`).join('\n');
const uncertaintyLines = (p.analysis.uncertainties ?? []).slice(0,5).map(item => `• ${safeText(item,200)}`).join('\n');
const sourceLines = (p.sources ?? []).slice(0,10).map(item => `• ${safeText(item.name,120)} — ${safeText(item.discovered_at,80)}`).join('\n');
const card = {$schema:'http://adaptivecards.io/schemas/adaptive-card.json',type:'AdaptiveCard',version:'1.2',body:[{type:'TextBlock',size:'Large',weight:'Bolder',color:'Attention',wrap:true,text:`Threat Claim Monitor — ${safeText(p.organization.name,160)}`},{type:'TextBlock',wrap:true,text:`${safeText(p.disclaimer,300)}`},{type:'FactSet',facts:[{title:'Alert ID',value:safeText(p.alert_id,80)},{title:'Organisation',value:safeText(p.organization.name,160)},{title:'Victime déclarée',value:safeText(p.claim.victim_name,180)},{title:'Acteur',value:safeText(p.claim.threat_actor,160)},{title:'Vérification',value:safeText(p.claim.verification_status,80)},{title:'Correspondance',value:`${safeText(p.match.method,100)} — ${Number(p.match.confidence_score)} / 100`},{title:'Première observation',value:safeText(p.claim.first_seen_at,80)},{title:'Dernière observation',value:safeText(p.claim.last_seen_at,80)}]},{type:'TextBlock',weight:'Bolder',spacing:'Medium',text:'Analyse'},{type:'TextBlock',wrap:true,text:safeText(p.analysis.summary_fr,600)},{type:'TextBlock',weight:'Bolder',spacing:'Medium',text:'Faits observés'},{type:'TextBlock',wrap:true,text:factLines||'Aucun fait structuré'},{type:'TextBlock',weight:'Bolder',spacing:'Medium',text:'Incertitudes'},{type:'TextBlock',wrap:true,text:uncertaintyLines||'Aucune incertitude structurée'},{type:'TextBlock',weight:'Bolder',spacing:'Medium',text:'Sources'},{type:'TextBlock',wrap:true,text:sourceLines||'Aucune source structurée'}]};
const teams_body = {type:'message',attachments:[{contentType:'application/vnd.microsoft.card.adaptive',contentUrl:null,content:card}]};
return {json:{dispatch_context:{notification_id:$json.notification_id,lease_token:$json.lease_token},teams_body}};

const source = $('Build safe Adaptive Card').item.json.dispatch_context;
const status = Number($json.statusCode ?? 200);
return {json:{delivery_result:{notification_id:source.notification_id,lease_token:source.lease_token,succeeded:true,response_status:status,response_excerpt:'teams workflow accepted',error_code:null}}};

const source = $('Build safe Adaptive Card').item.json.dispatch_context;
const status = Number($json.statusCode ?? $json.httpCode ?? $json.error?.statusCode ?? $json.error?.httpCode ?? $json.error?.status ?? 0);
const detail = JSON.stringify($json.error ?? {}).toLowerCase();
let error_code = 'connection_failed';
if (status === 401 || status === 403) error_code = 'delivery_rejected';
else if (status === 429) error_code = 'rate_limited';
else if (status >= 400 && status < 500) error_code = 'http_4xx';
else if (status >= 500) error_code = 'http_5xx';
else if (detail.includes('timeout') || detail.includes('timed out')) error_code = 'timeout';
else if (detail.includes('credential')) error_code = 'credential_unavailable';
return {json:{delivery_result:{notification_id:source.notification_id,lease_token:source.lease_token,succeeded:false,response_status:status||null,response_excerpt:null,error_code}}};
